}"}],"evidence":{"problem":"First R4 fixed registered cameras passed with limits; 8-GPU full-detail orthographic render showed the vegetation stops at the survey rectangle unrelated to physical material. Textures use a world material; outside surveyed core is an explicit artistic prior. All three initial crop panels are real renders and do not depict the final revised asset.","currentAsset":{"sha256":"493b3733f4afb4702b6182c8127160de5903c03f42a3d59cfdf0bd2de60bf55c","bytes":29902848},"firstR4AssetSha256":"959985d05424fcaa205f4819780255f75b7f1e5ad6e7a8f97d97ff7b7bf3533d","worldCoreXZMetres":[-20,24,-42,10],"expandedSafeEnvelopeXZMetres":[-32,36,-54,22],"actualNewExports":{"camera":{"bytes":1418276,"sha256":"58f5da32ab028a2e0ecbb727fb0bca955e1f527fc2c140e6cfcee7bae72f2e06","stats":{"seed":1942029223,"fieldTufts":510687,"tufts":26610,"blades":196585,"drawCalls":8,"nearBlades":0,"middleBlades":54327,"farBlades":142258}},"full":{"bytes":26648024,"sha256":"980b3ee316686056c30c0de74979d64ee146d474dca4c6b3943abff7c5a50f72","stats":{"seed":1942029223,"fieldTufts":510687,"tufts":510687,"blades":20683136,"drawCalls":4,"nearBlades":20683136,"middleBlades":0,"farBlades":0}}},"source":{"file":"lib/capture-meadow.ts","sha256":"8c00525894cdb3f50b3047a9d2ade12109a68974e050d08f0cc94af7225e3907","firstLine":20,"lastLine":37,"code":"const smooth = (a:number,b:number,x:number)=>{const t=THREE.MathUtils.clamp((x-a)/(b-a),0,1);return t*t*(3-2*t);};
